type EditProjectSidebarDialogState = {
  searchQuery: string
  overviewExpandState: KeyValue<ProjectId, ExpandState>
  allProjectsExpandState: KeyValue<ProjectId, ExpandState>
  searchProjectsExpandState: KeyValue<ProjectId, ExpandState>
}

const StateKeyByGroup = {
  favorites: 'overviewExpandState',
  all: 'allProjectsExpandState',
  search: 'searchProjectsExpandState',
} as const
const header = (
  <div>
    <H1 className={styles.header}>{'Configure Favorites'}</H1>
    <div className={styles.shortcuts}>
      {'Toggle favorites: Enter'}
      <br />
      {`without subprojects: ${cmdOrCtrl}+Enter`}
      <br />
      {`Move: ${cmdOrCtrl}+↑↓`}
    </div>
  </div>
)

const makeGetItems = (projectId: ProjectId) => {
  const getAllProjectsTree: (
    state: State,
    filter: TreeFilter,
  ) => ProjectsTreeType | null | undefined = createSelector(
    (state: State) => getProjectsReady(state, projectId),
    (state: State) => getProjectsData(state, projectId),
    getBuildTypesHash,
    getPipelinesHash,
    getProjectsHash,
    (_: State, filter: TreeFilter) => filter,
    (ready, data, buildTypes, pipelines, projects, filter) =>
      convertDataToTree({
        ready,
        data: data.filter(id => !projects[id]?.archived),
        buildTypes,
        pipelines,
        projects,
        group: 'all',
        filter,
      }),
  )
  return createSelector(
    (state: State) => getOverviewReady(state),
    getOverviewData,
    getOverviewBuildTypesHash,
    getOverviewPipelinesHash,
    getOverviewProjectsHash,
    getHasFavoriteProjects,
    getAllProjectsTree,
    (state: State) => state.togglingOverview,
    (_: State, filter: TreeFilter) => filter,
    (_: State, __: TreeFilter, overviewExpandState: KeyValue<ProjectId, ExpandState>) =>
      overviewExpandState,
    (
      _: State,
      __: TreeFilter,
      ___: KeyValue<ProjectId, ExpandState>,
      allProjectsExpandState: KeyValue<ProjectId, ExpandState> | null | undefined,
    ) => allProjectsExpandState,
    (
      overviewReady,
      overviewData,
      overviewBuildTypesHash,
      overviewPipelineHash,
      overviewProjectsHash,
      hasFavoriteProjects,
      allProjectsTree,
      togglingOverview,
      filter,
      overviewExpandState,
      allProjectsExpandState,
    ) => {
      const defaultOverviewTree = createDefaultOverviewTree(
        overviewReady,
        overviewData,
        overviewBuildTypesHash,
        overviewPipelineHash,
        overviewProjectsHash,
        filter,
      )
      const overviewTree = upgradeTreeByExpandState({
        defaultTree: defaultOverviewTree,
        expandState: overviewExpandState,
        baseLevel: 0,
      })
      const getHasReorderedSiblings = memoize((itemType: string) =>
        memoize((parentId: ProjectId) => {
          const overviewSiblings: ProjectsTreeItem[] = []
          const siblings: ProjectsTreeItem[] = []
          const overviewTreeData = overviewTree.data
          const overviewTreeLength = overviewTreeData.length
          /* Info: Performance improvement
           * Here is using getting the project through the key
           * to avoid looping all projects every time and decrease amount of nested loops
           */
          for (let i = 0; i < overviewTreeLength; i++) {
            const item = overviewTreeData[i]

            if (item.itemType === itemType && item.parentId === parentId) {
              const hashKey = `${currentServerId}_${item.itemType}_${item.id}`
              const hashItem = allProjectsTree?.hash?.get(hashKey)

              overviewSiblings.push(item)

              if (hashItem) {
                siblings.push(hashItem)
              }
            }
          }

          siblings.sort(({index}, {index: prevIndex}) => index! - prevIndex!)

          return overviewSiblings.some(function someFavoriteProjectsSiblings(sibling, i) {
            return siblings[i]?.id !== sibling.id
          })
        }),
      )
      const overviewDataSet = new Set(overviewData)
      const upgradedOverviewData = overviewTree.data.map((item: ProjectsTreeItem) => ({
        ...item,
        isStarred: getIsStarred({
          item,
          togglingOverview,
          overviewData: overviewDataSet,
          overviewProjectsHash,
        }),
        hasReorderedChildren:
          item.itemType === 'project' &&
          (getHasReorderedSiblings('project')(item.id) ||
            getHasReorderedSiblings('buildType')(item.id)),
      }))
      const upgradedAllProjectsData = upgradeTreeByExpandState({
        defaultTree: allProjectsTree,
        expandState: allProjectsExpandState,
        baseLevel: 0,
        shift: -1,
      }).data.map((item: ProjectsTreeItem) => ({
        ...item,
        isStarred: getIsStarred({
          item,
          togglingOverview,
          overviewData: overviewDataSet,
          overviewProjectsHash,
        }),
      }))
      return {
        items: mergeProjectsForSidebar(
          upgradedOverviewData,
          hasFavoriteProjects,
          upgradedAllProjectsData,
          createAllProjectsTitleItem(false, true),
          false,
          true,
          true,
        ),
        rootHasReorderedChildren: getHasReorderedSiblings('project')(ROOT_PROJECT_ID),
      }
    },
  )
}

type Props = {
  projectId: ProjectId
}

function EditProjectSidebarDialogContent({projectId}: Props) {
  const initialOverviewExpandState = useOneOffSelector(getOverviewExpandState)
  const initialAllProjectsExpandState = useOneOffSelector(getAllProjectsExpandState)
  const [
    {searchQuery, overviewExpandState, allProjectsExpandState, searchProjectsExpandState},
    {setSearchQuery, toggleExpandState},
  ] = useSlice<
    EditProjectSidebarDialogState,
    {
      setSearchQuery: string
      toggleExpandState: {
        id: ProjectId
        expanded: boolean
        group: keyof typeof StateKeyByGroup
      }
    }
  >(
    {
      setSearchQuery: (state, query) => ({
        ...state,
        searchQuery: query,
        searchProjectsExpandState: {},
      }),

      toggleExpandState(state, {id, expanded, group}) {
        const key = StateKeyByGroup[group]
        return Object.assign(
          {},
          state,
          keyValue(key, {
            ...state[key],
            ...keyValue(id, {
              id,
              expandState: expanded ? 'EXPANDED' : 'COLLAPSED',
            }),
          }),
        )
      },
    },
    {
      searchQuery: '',
      overviewExpandState: initialOverviewExpandState,
      allProjectsExpandState: initialAllProjectsExpandState,
      searchProjectsExpandState: {},
    },
  )
  const projectsReady = useAppSelector(state => getProjectsReady(state, projectId))
  restApi.endpoints.getAllProjectsNormalized.useQuerySubscription(
    projectsReady ? skipToken : getProjectsArg(projectId ?? ROOT_PROJECT_ID, sidebarOptions),
  )
  const getItems = useMemo(() => makeGetItems(projectId), [projectId])
  const filter = useMemo(() => ({parentId: projectId}), [projectId])
  const searchItems = useSearchItems(filter, searchQuery, searchProjectsExpandState)
  const {items, rootHasReorderedChildren} = useAppSelector(state =>
    searchQuery.length > 0
      ? searchItems
      : getItems(state, filter, overviewExpandState, allProjectsExpandState),
  )
  const overviewReady = useAppSelector(getOverviewReady)
  const dispatch = useAppDispatch()
  const toggleOverviewAction = useCallback(
    (node: ProjectOrBuildTypeNode, on: boolean, skipSubprojects?: boolean) =>
      dispatch(toggleOverview(node, on, skipSubprojects)),
    [dispatch],
  )
  const onChangeSearchActive = useCallback(
    (active: boolean) => {
      if (!active) {
        setSearchQuery('')
      }
    },
    [setSearchQuery],
  )
  return (
    <>
      {header}
      <div className={styles.content}>
        <EditProjectSidebarContext.Provider value>
          <ProjectsTree
            dispatch={dispatch}
            isEdit
            ready={overviewReady && projectsReady}
            className={styles.tree}
            contentClassName={styles.treeContent}
            itemParentClassName={styles.treeItemParent}
            items={items}
            toggleExpandState={(id, expanded, group) => {
              if (group !== 'none') {
                toggleExpandState({
                  id,
                  expanded,
                  group: group as keyof typeof StateKeyByGroup,
                })
              }
            }}
            toggleExpandAll={noop}
            toggleOverview={toggleOverviewAction}
            searchActive
            searchQuery={searchQuery}
            renderSearch={({sidebarRef, collapsed, ...searchProps}) => (
              <ProjectTreeSearch
                {...searchProps}
                className={styles.search}
                searchQuery={searchQuery}
                onChangeQuery={setSearchQuery}
                onChangeActive={onChangeSearchActive}
                propagateEscape
                wrapperClassName={styles.searchWrapper}
              />
            )}
            moveProject={(...args) => dispatch(moveProject(...args))}
            moveBuildType={(...args) => dispatch(moveBuildType(...args))}
            isPopup
          >
            <Panel className={styles.footer}>
              {'Changes are applied automatically'}
              {rootHasReorderedChildren && (
                <Button
                  className={styles.resetOrder}
                  onClick={() => dispatch(resetOrderInRootProject())}
                >
                  {'Reset to default order'}
                </Button>
              )}
            </Panel>
          </ProjectsTree>
        </EditProjectSidebarContext.Provider>
      </div>
    </>
  )
}

export function EditProjectSidebarDialog({isOpened, closeDialog, projectId}: DialogProps<Props>) {
  return (
    <Dialog
      label="Configure Sidebar"
      show={isOpened}
      onCloseAttempt={closeDialog}
      contentClassName={styles.dialog}
      showCloseButton
      closeButtonInside
    >
      <EditProjectSidebarDialogContent projectId={projectId} />
    </Dialog>
  )
}

export default withDialogContainer<Props>(
  DialogType.EDIT_SIDEBAR,
  (_, {projectId}) => projectId,
)(EditProjectSidebarDialog)
