import {skipToken} from '@reduxjs/toolkit/query'
import {useCallback, useEffect} from 'react'

import {useAppDispatch, useAppSelector} from '../../../../../hooks/react-redux'
import {getBuildTypeArg} from '../../../../../rest/buildTypes'
import {getSingleProjectArg, sidebarArg} from '../../../../../rest/projects'
import {getAllProjectsReady, getBuildType, getPipeline} from '../../../../../selectors'
import {getDefaultOverviewTree, matchSidebarItem} from '../../../../../selectors/projectTrees'
import {restApi} from '../../../../../services/rest'
import type {SidebarActiveItem} from '../../../../../types/projectTrees'
import {sidebarSettings} from '../../SidebarPanel.slices'

import {projectsSidebar} from './ProjectsSidebar.slices'

export function useProjectsSidebar() {
  const dispatch = useAppDispatch()
  const [fetchAllProjects] = restApi.endpoints.getAllProjectsNormalized.useLazyQuerySubscription()
  const projectsReady = useAppSelector(state => getAllProjectsReady(state))

  const searchQuery = useAppSelector(state => state.projectsSidebar.searchQuery)
  const searchActive = useAppSelector(state => state.projectsSidebar.searchActive)
  const collapsed = useAppSelector(state => state.sidebarSettings.collapsed)

  const changeSidebarSearchQuery = useCallback(
    (query: string) => {
      dispatch(projectsSidebar.actions.changeSearchQuery(query))
    },
    [dispatch],
  )

  const changeSidebarSearchActive = useCallback(
    (active: boolean) => {
      dispatch(projectsSidebar.actions.changeSearchActive(active))
      dispatch(sidebarSettings.actions.setAutoCollapseDisabled(active))

      if (!active) {
        dispatch(projectsSidebar.actions.changeSearchQuery(''))
      }
    },
    [dispatch],
  )

  useEffect(() => {
    if (collapsed && searchActive) {
      changeSidebarSearchActive(false)
    }
  }, [changeSidebarSearchActive, collapsed, searchActive])

  useEffect(() => {
    if (searchQuery !== '' && searchActive && !projectsReady) {
      fetchAllProjects(sidebarArg)
    }
  }, [fetchAllProjects, projectsReady, searchActive, searchQuery])

  return {
    collapsed,
    searchQuery,
    searchActive,
    changeSidebarSearchQuery,
    changeSidebarSearchActive,
  }
}

export const useActiveItem = (activeItem: SidebarActiveItem | null) => {
  const {id, nodeType, group} = activeItem ?? {}
  const activeItemProjectId = useAppSelector(state => {
    if (nodeType === 'bt') {
      return getBuildType(state, id)?.projectId
    } else if (nodeType === 'pipeline') {
      return getPipeline(state, id)?.parentProject.id
    } else if (nodeType === 'project') {
      return id
    }
    return null
  })
  restApi.endpoints.getProjectNormalized.useQuerySubscription(
    activeItemProjectId
      ? getSingleProjectArg(activeItemProjectId, {
          withBuildTypes: true,
          withLinksAvailability: true,
          withAncestorProjects: true,
        })
      : skipToken,
  )
  restApi.endpoints.getBuildTypeNormalized.useQuerySubscription(
    nodeType === 'bt' && id != null ? getBuildTypeArg(id) : skipToken,
  )
  const dispatch = useAppDispatch()
  const overviewTree = useAppSelector(state => getDefaultOverviewTree(state)?.data)
  useEffect(() => {
    if (nodeType === 'bt' || nodeType === 'project' || nodeType === 'pipeline') {
      const item = {...activeItem, group: 'favorites'} as SidebarActiveItem
      const favoriteItemOpen = group !== 'all' && !!overviewTree?.some(matchSidebarItem(item))
      const activeBuildTypeId = nodeType === 'bt' ? id : null
      const activePipelineId = nodeType === 'pipeline' ? id : null
      const activeItemData = {
        activeBuildTypeId,
        activePipelineId,
        activeProjectId: activeItemProjectId,
        isFavoriteItemOpen: favoriteItemOpen,
      }
      dispatch(projectsSidebar.actions.changeActiveItem(activeItemData))
    } else {
      dispatch(
        projectsSidebar.actions.changeActiveItem({
          activeBuildTypeId: null,
          activeProjectId: null,
          activePipelineId: null,
          isFavoriteItemOpen: nodeType === 'link',
        }),
      )
    }
  }, [activeItem, activeItemProjectId, dispatch, group, id, nodeType, overviewTree])
}
