import Toggle, {Size} from '@jetbrains/ring-ui-built/components/toggle/toggle'
import classNames from 'classnames'
import type {CSSProperties} from 'react'

import {toggleArchivedProjectsInSidebar} from './SidebarFooter.actions'

import styles from './SidebarFooter.module.css'

import {useAppDispatch, useAppSelector} from 'src/hooks/react-redux'

type Props = {
  className?: string
  style?: CSSProperties
  showArchived?: boolean
  toggleArchived?: () => void
}

export default function SidebarFooter({className, style, showArchived, toggleArchived}: Props) {
  const dispatch = useAppDispatch()
  const toggleArchivedProjects: () => void =
    toggleArchived ??
    (() => {
      dispatch(toggleArchivedProjectsInSidebar())
    })
  const showArchivedProjects = useAppSelector(
    state => showArchived ?? state.projectsSidebar.showArchivedProjects,
  )

  return (
    <div className={classNames(className, styles.container)} style={style} data-inside-sidebar>
      <Toggle
        size={Size.Size14}
        className={styles.archiveToggle}
        defaultChecked={showArchivedProjects}
        onChange={toggleArchivedProjects}
        leftLabel={<span>{'Show archived'}</span>}
      />
    </div>
  )
}
