import AddIcon from '@jetbrains/icons/add.svg'
import SettingsIcon from '@jetbrains/icons/settings.svg'
import Button from '@jetbrains/ring-ui-built/components/button/button'
import Icon from '@jetbrains/ring-ui-built/components/icon/icon'
import Tooltip from '@jetbrains/ring-ui-built/components/tooltip/tooltip'
import {skipToken} from '@reduxjs/toolkit/query'
import * as React from 'react'
import {useCallback, useContext, useEffect, useMemo} from 'react'
import {useHref, useLinkClickHandler} from 'react-router'

import {
  useFederationServers,
  useProjectsForSidebar,
  useSearchProjectsTreeMerged,
} from '../../../../../hooks/projectTrees'
import {useAppDispatch, useAppSelector} from '../../../../../hooks/react-redux'
import {usePermission} from '../../../../../hooks/usePermission'
import {getProjectsArg} from '../../../../../rest/projects'
import {getCreateProjectHref} from '../../../../../routes'
import {getProjectsReady} from '../../../../../selectors'
import {
  getAllAncestorProjectsReady,
  getHasFavoriteProjects,
} from '../../../../../selectors/projectTrees'
import {restApi} from '../../../../../services/rest'
import {Permission, ROOT_PROJECT_ID} from '../../../../../types'
import {emptyMap} from '../../../../../utils/empty'
import {EditProjectSidebarContext} from '../../../../common/EditProjectSidebar/EditProjectSidebar.context'
import EditProjectSidebarDialog from '../../../../common/EditProjectSidebar/EditProjectSidebarDialog'
import ProjectsTree from '../../../../common/ProjectsTree/ProjectsTree'
import {ProjectsTreeContext} from '../../../../common/ProjectsTree/ProjectsTree.context'
import SidebarFooter from '../../../../common/SidebarFooter/SidebarFooter'
import SidebarSearch from '../../../../common/SidebarSearch/SidebarSearch'
import type {SidebarSearchOwnProps} from '../../../../common/SidebarSearch/SidebarSearch.types'
import {isCreateProjectNewUiEnabled} from '../../../../pages/PipelinesPages/utils/featureToggles'
import SidebarHeader from '../SidebarHeader/SidebarHeader'
import SidebarHeaderShadow from '../SidebarHeaderShadow/SidebarHeaderShadow'
import {useSidebarScroll} from '../SidebarPanelContent.hooks'
import {getSidebarSearchPlaceholder} from '../SidebarPanelContent.utils'

import {expandParents} from './ProjectsSidebar.actions'
import {useProjectsSidebar} from './ProjectsSidebar.hooks'
import {projectsSidebar} from './ProjectsSidebar.slices'
import type {Props} from './ProjectsSidebar.types'

import styles from './ProjectsSidebar.module.css'

function ProjectsSidebar({
  statuses,
  activeItem,
  changeActiveItem,
  toggleExpandState,
  toggleExpandAll,
  width,
  toggleOverview,
  reloadProjects,
  className,
  ready,
  projectsReady,
  federationServersKey,
}: Props) {
  const dispatch = useAppDispatch()

  const [scrollState, onScroll] = useSidebarScroll()
  const {
    collapsed,
    searchQuery,
    searchActive,
    changeSidebarSearchQuery,
    changeSidebarSearchActive,
  } = useProjectsSidebar()

  const activeItemReady = useAppSelector(state => getAllAncestorProjectsReady(state))
  const allProjectsCollapsed = useAppSelector(state => state.projectsSidebar.allProjectsCollapsed)
  const projectsLoading = React.useMemo(() => {
    const isSearchActive = searchActive && searchQuery !== ''
    const isItemNotReady = activeItem && allProjectsCollapsed && !activeItemReady
    const isSearching = !projectsReady && (isSearchActive || !allProjectsCollapsed)
    return isItemNotReady || isSearching
  }, [activeItem, activeItemReady, allProjectsCollapsed, projectsReady, searchActive, searchQuery])

  const projectsForSidebar = useProjectsForSidebar()
  const federationServers = useFederationServers(federationServersKey)
  const searchProjectsTreeMerged = useSearchProjectsTreeMerged(federationServersKey)
  const userCanEdit = usePermission(Permission.CHANGE_OWN_PROFILE, ROOT_PROJECT_ID)
  const hasFavoriteProjects = useAppSelector(getHasFavoriteProjects)

  const isEdit = React.useContext(EditProjectSidebarContext)

  const activeProjectId = activeItem?.nodeType === 'project' ? activeItem.id : undefined
  const projectReady = useAppSelector(state => getProjectsReady(state, activeProjectId))
  restApi.endpoints.getAllProjectsNormalized.useQuerySubscription(
    !activeProjectId || projectReady
      ? skipToken
      : getProjectsArg(activeProjectId, {
          withBuildTypes: true,
          withAncestorProjects: true,
          withLinksAvailability: true,
        }),
  )

  const withArchived = useAppSelector(state => state.projectsSidebar.showArchivedProjects)
  useEffect(() => {
    reloadProjects(federationServers, withArchived)
  }, [reloadProjects, federationServers, withArchived])

  const items = useMemo(
    () => (searchActive && searchQuery ? searchProjectsTreeMerged.data : projectsForSidebar),
    [projectsForSidebar, searchActive, searchProjectsTreeMerged.data, searchQuery],
  )
  const searchProjectsTreeHash = searchProjectsTreeMerged.hash || emptyMap

  const filteredItems = React.useMemo(
    () =>
      isEdit
        ? items.filter(item => item.itemType !== 'link' && item.id !== ROOT_PROJECT_ID)
        : items,
    [isEdit, items],
  )

  useEffect(() => {
    if (ready && !projectsLoading && activeItemReady && activeItem != null) {
      dispatch(expandParents(activeItem, searchProjectsTreeHash))
    }
  }, [activeItem, activeItemReady, dispatch, projectsLoading, ready, searchProjectsTreeHash])

  useEffect(() => {
    if (!hasFavoriteProjects) {
      dispatch(projectsSidebar.actions.changeAllProjectsCollapsed(false))
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  const renderSearch = useCallback(
    ({sidebarRef, ...searchProps}: SidebarSearchOwnProps) => (
      <SidebarSearch
        placeholder={getSidebarSearchPlaceholder(width, 'Search by name')}
        searchQuery={searchQuery}
        searchActive={searchActive}
        changeSidebarSearchQuery={changeSidebarSearchQuery}
        changeSidebarSearchActive={changeSidebarSearchActive}
        {...searchProps}
      />
    ),
    [changeSidebarSearchActive, changeSidebarSearchQuery, searchActive, searchQuery, width],
  )

  const canCreateSubProject = usePermission(Permission.CREATE_SUB_PROJECT, ROOT_PROJECT_ID)

  const {isAdmin} = useContext(ProjectsTreeContext)
  const to = getCreateProjectHref(ROOT_PROJECT_ID)
  const href = useHref(to)
  const onClick = useLinkClickHandler(to)
  const renderSearchWithWrapper = useCallback(
    (props: SidebarSearchOwnProps) => (
      <SidebarHeaderShadow
        sidebarCollapsed={collapsed}
        showShadow={!collapsed && scrollState?.isScrollAtStart === false}
      >
        <SidebarHeader
          sidebarName={
            <>
              {'Projects'}
              {isAdmin && <Icon glyph={SettingsIcon} className={styles.settingsIcon} />}
            </>
          }
          search={renderSearch(props)}
          headerButton={
            canCreateSubProject ? (
              <Tooltip title={'Create'}>
                {isCreateProjectNewUiEnabled ? (
                  <Button icon={AddIcon} href={href} onClick={onClick} />
                ) : (
                  <Button
                    icon={AddIcon}
                    title="Create new project"
                    href={getCreateProjectHref(ROOT_PROJECT_ID)}
                  />
                )}
              </Tooltip>
            ) : undefined
          }
        />
      </SidebarHeaderShadow>
    ),
    [
      canCreateSubProject,
      collapsed,
      href,
      isAdmin,
      onClick,
      renderSearch,
      scrollState?.isScrollAtStart,
    ],
  )

  const tree = useMemo(
    () => (
      <ProjectsTree
        contentClassName={styles.sidebarContent}
        items={filteredItems}
        statuses={statuses}
        activeItem={activeItem}
        changeActiveItem={changeActiveItem}
        toggleExpandState={(projectId, expanded, group) =>
          toggleExpandState(projectId, expanded, group, searchProjectsTreeHash)
        }
        toggleExpandAll={toggleExpandAll}
        searchQuery={searchQuery}
        searchActive={searchActive}
        width={width}
        toggleOverview={toggleOverview}
        reloadProjects={() => reloadProjects(federationServers, withArchived)}
        collapsed={collapsed}
        className={className}
        ready={ready}
        allProjectsReady={!projectsLoading}
        userCanEdit={userCanEdit}
        dispatch={dispatch}
        onScroll={onScroll}
        renderSearch={renderSearchWithWrapper}
      />
    ),
    [
      activeItem,
      changeActiveItem,
      className,
      collapsed,
      dispatch,
      federationServers,
      filteredItems,
      onScroll,
      projectsLoading,
      ready,
      reloadProjects,
      renderSearchWithWrapper,
      searchActive,
      searchProjectsTreeHash,
      searchQuery,
      statuses,
      toggleExpandAll,
      toggleExpandState,
      toggleOverview,
      userCanEdit,
      width,
      withArchived,
    ],
  )

  return (
    <div className={styles.sidebar}>
      {tree}
      {!searchActive ? null : <SidebarFooter />}
      {userCanEdit && <EditProjectSidebarDialog projectId={ROOT_PROJECT_ID} />}
    </div>
  )
}

export default ProjectsSidebar
