import {fetchArchivedProjects} from '../../../actions/projects'
import type {AppThunk} from '../../../actions/types'
import {getFederationProjectsArg} from '../../../rest/projects'
import {restApi} from '../../../services/rest'
import {projectsSidebar} from '../../App/SidebarPanel/SidebarPanelContent/ProjectsSidebar/ProjectsSidebar.slices'

export const fetchProjectsForAllFederationServers =
  (federationServers: readonly string[], withArchived: boolean): AppThunk<any> =>
  dispatch => {
    for (let i = 0; i < federationServers.length; i++) {
      const federationServerId = federationServers[i]
      if (federationServerId != null) {
        dispatch(
          restApi.endpoints.getFederationProjectsNormalized.initiate(
            getFederationProjectsArg(federationServerId, withArchived),
          ),
        )
      }
    }
  }
export const toggleArchivedProjectsInSidebar = (): AppThunk<any> => (dispatch, getState) => {
  dispatch(projectsSidebar.actions.toggleArchivedProjectsInSidebar())
  const state = getState()

  if (state.projectsSidebar.showArchivedProjects) {
    dispatch(fetchArchivedProjects())
  }
}
